"""Browser tools for the model: a compact, numbered view of the page and actions on its elements.

The model decides where to go and what to do; these helpers only render what is on the screen (all frames, tables
as rows, interactive elements tagged with ids), perform the action the model chose, ride out flaky error pages and
expired sessions, and read documents (ZIP, PDF, text) the model chose to open.
"""
import asyncio
import io
import re
import zipfile

# Renders a frame's DOM as text lines. Interactive elements get a data-aid id the model refers to.
SNAPSHOT_JS = r"""
(prefix) => {
  const out = [];
  let n = 0;
  const vis = (el) => {
    const s = getComputedStyle(el);
    if (s.display === 'none' || s.visibility === 'hidden') return false;
    if (el.getAttribute('aria-hidden') === 'true' && !el.querySelector('input,select,button,a')) return false;
    return true;
  };
  const clean = (t) => (t || '').replace(/\s+/g, ' ').trim();
  const tag = (el) => {
    const id = prefix + (n++);
    el.setAttribute('data-aid', id);
    return id;
  };
  const label = (el) => {
    let l = '';
    if (el.id) { const lab = document.querySelector(`label[for="${CSS.escape(el.id)}"]`); if (lab) l = clean(lab.innerText); }
    if (!l) { const lab = el.closest('label'); if (lab) l = clean(lab.innerText).slice(0, 80); }
    return l || el.getAttribute('aria-label') || el.getAttribute('placeholder') || el.getAttribute('title') || '';
  };
  const walk = (node, depth) => {
    if (node.nodeType === 3) { const t = clean(node.textContent); if (t) out.push(t); return; }
    if (node.nodeType !== 1) return;
    const el = node, name = el.tagName.toLowerCase();
    if (['script', 'style', 'noscript', 'template', 'svg', 'head'].includes(name)) return;
    if (!vis(el)) return;
    if (name === 'iframe' || name === 'frame') { out.push(`[iframe src=${el.getAttribute('src') || ''} name=${el.name || ''}] (content shown below as FRAME)`); return; }
    if (name === 'canvas') { const t = el.getAttribute('aria-label') || el.getAttribute('title') || clean(el.innerText); out.push(`[canvas${t ? ': ' + t : ''}]`); return; }
    if (name === 'a' && el.hasAttribute('href')) {
      out.push(`[${tag(el)}]<a "${clean(el.innerText) || el.getAttribute('title') || el.getAttribute('aria-label') || ''}" href=${el.getAttribute('href')}${el.getAttribute('download') !== null ? ' download' : ''}>`); return;
    }
    if (name === 'button' || (name === 'input' && ['submit', 'button', 'reset'].includes(el.type))) {
      out.push(`[${tag(el)}]<button "${clean(el.innerText) || el.value || el.getAttribute('aria-label') || ''}"${el.disabled ? ' disabled' : ''}>`); return;
    }
    if (name === 'input') {
      if (el.type === 'hidden') return;
      const extra = (el.type === 'checkbox' || el.type === 'radio') ? ` checked=${el.checked}` : ` value="${el.value}"`;
      out.push(`[${tag(el)}]<input type=${el.type} name=${el.name}${extra} label="${label(el)}"${el.required ? ' required' : ''}${el.disabled ? ' disabled' : ''}${el.readOnly ? ' readonly' : ''}>`); return;
    }
    if (name === 'textarea') { out.push(`[${tag(el)}]<textarea name=${el.name} label="${label(el)}" value="${el.value}">`); return; }
    if (name === 'select') {
      const opts = [...el.options].map(o => (o.selected ? '*' : '') + `${o.value}=${clean(o.text)}`).join(' | ');
      out.push(`[${tag(el)}]<select name=${el.name} label="${label(el)}" options: ${opts}>`); return;
    }
    if (name === 'summary') { out.push(`[${tag(el)}]<summary "${clean(el.innerText)}">`); return; }
    if (name === 'details' && !el.open) {
      const s = el.querySelector('summary'); if (s) walk(s, depth);
      out.push('(collapsed: click the summary to open)'); return;
    }
    if (name === 'tr') {
      const cells = [...el.children].map(c => {
        const inner = [];
        const save = out.length;
        for (const ch of c.childNodes) walk(ch, depth + 1);
        const parts = out.splice(save);
        return parts.join(' ');
      });
      out.push('| ' + cells.join(' | ') + ' |'); return;
    }
    if (el.getAttribute('role') === 'tooltip' || el.getAttribute('title')) {
      // keep tooltips: they often carry details
    }
    const block = /^(div|p|h[1-6]|li|section|article|header|footer|main|nav|aside|form|fieldset|legend|dl|dt|dd|table|thead|tbody|caption|ul|ol|pre|blockquote|br|hr)$/.test(name);
    if (/^h[1-6]$/.test(name)) { out.push('#'.repeat(+name[1]) + ' ' + clean(el.innerText)); return; }
    if (el.onclick || el.getAttribute('role') === 'button' || el.getAttribute('role') === 'tab' || el.getAttribute('tabindex') === '0') {
      const t = clean(el.innerText);
      if (t && t.length < 120 && !el.querySelector('a,button,input,select')) { out.push(`[${tag(el)}]<clickable "${t}">`); return; }
    }
    const title = el.getAttribute('title');
    if (title && name !== 'iframe') out.push(`(title: ${clean(title)})`);
    for (const ch of el.childNodes) walk(ch, depth + 1);
    if (block) out.push('\n');
  };
  walk(document.body || document.documentElement, 0);
  // join: inline pieces on one line, block breaks as newlines
  let text = '';
  for (const piece of out) {
    if (piece === '\n') { if (!text.endsWith('\n')) text += '\n'; }
    else if (piece.startsWith('|') || piece.startsWith('#') || piece.startsWith('[')) { if (!text.endsWith('\n') && text) text += '\n'; text += piece + '\n'; }
    else text += (text && !text.endsWith('\n') ? ' ' : '') + piece;
  }
  return text.replace(/\n{2,}/g, '\n');
}
"""

